import{c as e,Q as r,j as t,m as p}from"./chunks/framework.hhGiamYR.js";const m=JSON.parse('{"title":"我把自己变成了一头驴——关于《金驴记》、变形，与一个被罢官的人如何不写檄文","description":"","frontmatter":{"date":"2026-08-16T00:00:00.000Z","title":"我把自己变成了一头驴——关于《金驴记》、变形，与一个被罢官的人如何不写檄文"},"headers":[],"relativePath":"research/golden-ass/index.md","filePath":"research/golden-ass/index.md"}'),o={name:"research/golden-ass/index.md"};function l(i,a,n,s,h,c){return r(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="我把自己变成了一头驴" tabindex="-1">我把自己变成了一头驴 <a class="header-anchor" href="#我把自己变成了一头驴" aria-label="Permalink to &quot;我把自己变成了一头驴&quot;">​</a></h1><p>我这一生写过不少东西。给十人委员会写急件，给教皇写信，给君主写书。但有一部作品，我写它的时候，用的不是国务秘书的笔，也不是史官的笔——我用的是一头驴的嗓子。</p><p>这件事得从 1512 年说起。美第奇家族回来了，共和国倒了，我丢了官。次年我还被卷进一场阴谋，抓起来，吊刑六次。后来我活了下来，被放逐到圣卡夏诺乡间，每天砍柴、打鸟、去酒馆跟人赌骰子。换作别人，这时候大概会写一篇檄文，痛骂命运，控诉不公。</p><p>我没有。我写了一首把「自己变成一头驴」的诗。它叫《金驴记》。</p><hr><h2 id="变形不是逃避-是换一双眼睛" tabindex="-1">变形不是逃避，是换一双眼睛 <a class="header-anchor" href="#变形不是逃避-是换一双眼睛" aria-label="Permalink to &quot;变形不是逃避，是换一双眼睛&quot;">​</a></h2><p>诗的开头，我是这么写的：</p><blockquote><p>📖 <strong>原文</strong>：《金驴记》第一章</p><p>「种种的偶遇、哀痛和苦楚，我以驴子的外形所遭受了的，我都要去歌唱，只要机运女神允许。」</p><p>— 全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/04-%E9%87%91%E9%A9%B4%E8%AE%B0.md" target="_blank" rel="noreferrer">《金驴记》</a></p></blockquote><p>注意那个措辞——不是「我要控诉」，是「我要歌唱」。一个刚被吊刑六次、丢官流放的人，说他要歌唱自己变成驴之后遭受的一切。这口气不是认命，是挑衅。你把我打成这样，那我就把这副样子唱给你听。</p><p>《金驴记》写于 1517 至 1518 年之间，用的是但丁的三行体。我让诗里的叙述者——也就是我——被一位牧羊的女主人引领着，四脚着地，爬过森林，混进兽群。有一处，女主人对我下了这样一道命令：</p><blockquote><p>📖 <strong>原文</strong>：《金驴记》第三章</p><p>「因此首先就需要改变／你那人的外形，而且没有了它／你再和其他野兽一道来我这进食。」</p><p>— 全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/04-%E9%87%91%E9%A9%B4%E8%AE%B0.md" target="_blank" rel="noreferrer">《金驴记》</a></p></blockquote><p>这句话我琢磨了很多年。你被剥夺了人的资格——官职、公民身份、发言权——之后，还能不能开口？直接对抗已经不可能了，檄文只会让自己死得更快。那我就变形。变成驴，从动物的高度，低头看人类的一切荒唐：江湖郎中骗钱、医生靠病人的病痛过活、教士为金银被折磨、君主被自己的人民变成僭主。当你不被允许以臣子的身份进谏时，你还可以让自己变成笑料，让笑声替你把真话说出来。</p><hr><h2 id="讽刺是最锋利的武器" tabindex="-1">讽刺是最锋利的武器 <a class="header-anchor" href="#讽刺是最锋利的武器" aria-label="Permalink to &quot;讽刺是最锋利的武器&quot;">​</a></h2><p>这诗最著名的一句，出在第四章。女主人说我这一路受苦，终会「获得好处」。我是这么回答的：</p><blockquote><p>📖 <strong>原文</strong>：《金驴记》第四章</p><p>「我不怨天不尤人，／也不愿哀叹这险恶的命运，／因为我已惯于损害而非益处。」</p><p>— 全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/04-%E9%87%91%E9%A9%B4%E8%AE%B0.md" target="_blank" rel="noreferrer">《金驴记》</a></p></blockquote><p>「已惯于损害而非益处」——这句话不是放弃，是在对命运笑。我是在告诉机运女神：你压不垮我，我早就习惯了你这一套。真正的抵抗未必是拔剑，也可以是先一步自嘲，把敌人准备用来羞辱你的那句话，自己抢着说出来。一个会自嘲的失败者，人们会伸手扶他一把；一个只会怨天尤人的失败者，人们绕着他走。</p><p>同一个能拆解博尔贾蛇蝎手腕的人，也能写牧羊女的黄金秀发、写一头瘦骨嶙峋的驴活像「八月里的蔫儿黄瓜」。这不是精神分裂，是同一把刀换了握法。政治思考写不进急件里的，我就让喜剧角色在台上替我说；真相太痛不能直陈的，我就把它裹进诗里。文学于我，从来不是逃进书斋的避难所——它是我的第二件政治武器。</p><hr><p>有人会问：这样写，跟那个写《君主论》的你，是两个人吗？</p><p>不是。写《君主论》的时候，我教君主看清「事物实际上怎样」；写《金驴记》的时候，我让一头驴从更低的地方看清「人实际上怎样」。角度不同，看的是同一件事。严肃与荒唐，是我处理这个世界真相的两种手。需要冷的时候我冷，需要笑的时候我笑——但眼睛始终没离开过那件事：意大利正在被蹂躏，而人们还在互相欺骗。</p><p>所以，当你被逼进墙角、无路可退的时候，别急着写檄文。先想想，能不能把自己变成一头驴。</p><p>—— 尼科洛·马基雅维利，圣卡夏诺</p>',23)])])}const _=e(o,[["render",l]]);export{m as __pageData,_ as default};
